(3752600, 524572, 76217, '<td valign="top">Odd perspective, especially with the window in the background. She looks 6'' tall.</td>', 'Odd perspective, especially with the window in the background. She looks 6'' tall.', '2007-06-07 17:13:31.000000', NULL, 1),
(3752609, 526563, 78062, '<td valign="top">Nice take on the subject. Only became clear after scratching my chin...</td>', 'Nice take on the subject. Only became clear after scratching my chin...', '2007-06-07 17:15:55.000000', NULL, 1),
(3752610, 528470, 62187, '<td valign="top">I like the photo so I''ll be sympathetic to your dilemma and go with an 8 - why not!</td>', 'I like the photo so I''ll be sympathetic to your dilemma and go with an 8 - why not!', '2007-06-07 17:17:18.000000', NULL, 1),
(3752616, 526063, 78062, '<td valign="top">Is this staged? That picture look decidely super-imposed, or remarkably well exposed for basic editing. I''m not too sure which way to go, half of me thinks that if this was staged then it''s quite bad taste and I want to comdemn it... but if it isn''t then there''s something here- the flowers and the guy make the picture. I think the 9/11 picture is totally superfluous though and it almost seems like the title is taking the piss a bit.<br/> <br/>Great composition though and the skewed angle carries your eye across the picture.</td>', 'Is this staged? That picture look decidely super-imposed, or remarkably well exposed for basic editing. I''m not too sure which way to go, half of me thinks that if this was staged then it''s quite bad taste and I want to comdemn it... but if it isn''t then there''s something here- the flowers and the guy make the picture. I think the 9/11 picture is totally superfluous though and it almost seems like the title is taking the piss a bit. Great composition though and the skewed angle carries your eye across the picture.', '2007-06-07 17:19:32.000000', NULL, 1),
(3752617, 528478, 78062, '<td valign="top">Looks Sicilian to me. I can hear the Godfather theme in my head now.<br/> <br/>"I know it was you, Fredo..."</td>', 'Looks Sicilian to me. I can hear the Godfather theme in my head now. "I know it was you, Fredo..."', '2007-06-07 17:20:15.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3752619, 528559, 78062, '<td valign="top">Shame there''s no rain in the picture.</td>', 'Shame there''s no rain in the picture.', '2007-06-07 17:20:48.000000', NULL, 1),
