INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3760159, 528056, 4967, '<td valign="top">To me there is a bit too much surrounding the cat that I''m no really interested in.  I would have loved to see this adorable cat filling the frame substantially more.  Is the cat really that orange?  Love his eyes.</td>', 'To me there is a bit too much surrounding the cat that I''m no really interested in.  I would have loved to see this adorable cat filling the frame substantially more.  Is the cat really that orange?  Love his eyes.', '2007-06-09 12:45:13.000000', NULL, 1),
(3760161, 528792, 4967, '<td valign="top">LOL fun - quirky - unexpected question... I love the fact that the sword is just sitting there in the dark... looking totaly benign and normal.  Great job with lighting.  I really like this image!  Nicely done - 10 -</td>', 'LOL fun - quirky - unexpected question... I love the fact that the sword is just sitting there in the dark... looking totaly benign and normal.  Great job with lighting.  I really like this image!  Nicely done - 10 -', '2007-06-09 12:46:37.000000', NULL, 1),
(3760162, 528916, 35947, '<td valign="top">Great use of negative space.  Excellent lighting.  Feels tipped to the right though.</td>', 'Great use of negative space.  Excellent lighting.  Feels tipped to the right though.', '2007-06-09 12:47:13.000000', NULL, 1),
(3760165, 528121, 4967, '<td valign="top">For me this is more of a "what" than a why.  Unfortunately I don''t find it extremely visually appealing either... to each their own though.</td>', 'For me this is more of a "what" than a why.  Unfortunately I don''t find it extremely visually appealing either... to each their own though.', '2007-06-09 12:47:33.000000', NULL, 1),
(3760167, 528559, 35947, '<td valign="top">Very cool image.  Love the lines and color.</td>', 'Very cool image.  Love the lines and color.', '2007-06-09 12:48:29.000000', NULL, 1),
(3760168, 528364, 4967, '<td valign="top">Beautifully executed and layered image. How long was the exposure?  This should score well here.</td>', 'Beautifully executed and layered image. How long was the exposure?  This should score well here.', '2007-06-09 12:49:09.000000', NULL, 1),
(3760171, 528614, 4967, '<td valign="top">Nice black and white.  To me this image screams to be cropped down at the top into more of a panoramic.</td>', 'Nice black and white.  To me this image screams to be cropped down at the top into more of a panoramic.', '2007-06-09 12:49:55.000000', NULL, 1),
(3760176, 526672, 35947, '<td valign="top">Why wouldn''t you!!  That looks like fun!  Great capture and composition.</td>', 'Why wouldn''t you!!  That looks like fun!  Great capture and composition.', '2007-06-09 12:51:45.000000', NULL, 1),
(3760178, 528432, 4967, '<td valign="top">Great capture... Nice DOF.  I think I would have cropped down and up a tad. -9-</td>', 'Great capture... Nice DOF.  I think I would have cropped down and up a tad. -9-', '2007-06-09 12:53:25.000000', NULL, 1),
(3760181, 528744, 4967, '<td valign="top">I can''t decide whether I feel like this is too much or too little negative space.  It just doesn''t feel perfect to me.  Nicely done though.</td>', 'I can''t decide whether I feel like this is too much or too little negative space.  It just doesn''t feel perfect to me.  Nicely done though.', '2007-06-09 12:54:44.000000', NULL, 1),
(3760184, 529301, 4967, '<td valign="top">Now this image actually makes me ask "why" lol.  I think this might have looked better with more cropped off the top.  Because I feel you met the challenge and it''s technically very good... enjoy your -9- :-)  Did you set this up or find this?</td>', 'Now this image actually makes me ask "why" lol.  I think this might have looked better with more cropped off the top.  Because I feel you met the challenge and it''s technically very good... enjoy your -9- :-)  Did you set this up or find this?', '2007-06-09 12:56:47.000000', NULL, 1),
(3760188, 528286, 4967, '<td valign="top">honestly... I feel a better title would have been - "Why I booked a window seat"  This does not give me a negative feeling at all.</td>', 'honestly... I feel a better title would have been - "Why I booked a window seat"  This does not give me a negative feeling at all.', '2007-06-09 12:58:17.000000', NULL, 1),
(3760189, 526331, 35947, '<td valign="top">What beautiful blue eyes!  Great expression on the face.</td>', 'What beautiful blue eyes!  Great expression on the face.', '2007-06-09 12:58:30.000000', NULL, 1),
(3760198, 528783, 1024, '<td valign="top">This is a great image, however if I had not paused for more than a few seconds I would have missed the little bug.  This is a photo that must be studied to be totally appreciated.</td>', 'This is a great image, however if I had not paused for more than a few seconds I would have missed the little bug.  This is a photo that must be studied to be totally appreciated.', '2007-06-09 13:03:15.000000', NULL, 1),
