(3768729, 526795, 76430, '<td valign="top">Good blending of white pad with white background.</td>', 'Good blending of white pad with white background.', '2007-06-11 16:29:12.000000', NULL, 1),
(3768754, 528470, 76430, '<td valign="top">Good composition.  The light streaks, probably from a passing vehicle, are distracting.  I won''t get into the political satire in the title.</td>', 'Good composition.  The light streaks, probably from a passing vehicle, are distracting.  I won''t get into the political satire in the title.', '2007-06-11 16:34:07.000000', NULL, 1),
(3768826, 528207, 76430, '<td valign="top">Not a very clear picture, and it doesn''t seem to match the title.</td>', 'Not a very clear picture, and it doesn''t seem to match the title.', '2007-06-11 16:46:27.000000', NULL, 1),
(3768855, 524385, 76430, '<td valign="top">why?  Maybe that response is the challenge answer?  The focus and lighting is not very good.  And you misspelled pistachio.</td>', 'why?  Maybe that response is the challenge answer?  The focus and lighting is not very good.  And you misspelled pistachio.', '2007-06-11 16:51:18.000000', NULL, 1),
(3768864, 528260, 76430, '<td valign="top">Nice picture.  Quoting Edmund Hillary, but a much less intimidating peak.  Good lighting, focus.</td>', 'Nice picture.  Quoting Edmund Hillary, but a much less intimidating peak.  Good lighting, focus.', '2007-06-11 16:53:29.000000', NULL, 1),
(3768866, 526713, 42181, '<td valign="top">OK i can see what you were going for with the breakfast paper but IMO the plates detract from the impact of the image.</td>', 'OK i can see what you were going for with the breakfast paper but IMO the plates detract from the impact of the image.', '2007-06-11 16:54:04.000000', NULL, 1),
(3768872, 528595, 42181, '<td valign="top">Yep, i think you could only say "why"</td>', 'Yep, i think you could only say "why"', '2007-06-11 16:55:47.000000', NULL, 1),
(3768877, 525635, 76430, '<td valign="top">Good effect with the cards, but poor choice of background.  The model should be reacting more</td>', 'Good effect with the cards, but poor choice of background.  The model should be reacting more', '2007-06-11 16:57:03.000000', NULL, 1),
(3768880, 525448, 76430, '<td valign="top">I don''t get it</td>', 'I don''t get it', '2007-06-11 16:58:06.000000', NULL, 1),
(3768887, 528364, 76430, '<td valign="top">Good composition.  The front of the rowboat seems out of focus, but the dock is in focus.</td>', 'Good composition.  The front of the rowboat seems out of focus, but the dock is in focus.', '2007-06-11 16:58:59.000000', NULL, 1),
(3768899, 526317, 76430, '<td valign="top">Nice composition, but it all seems sort of hazy.  Close to rule of thirds on horizon and fisherman, but not quite.</td>', 'Nice composition, but it all seems sort of hazy.  Close to rule of thirds on horizon and fisherman, but not quite.', '2007-06-11 17:01:08.000000', NULL, 1),
(3768912, 529303, 76430, '<td valign="top">Beautiful colors.  The jet stream goes through the guy''s hand and rests on his head.  Wondering about meaning of title without comma after "Why".  Good rule of thirds.</td>', 'Beautiful colors.  The jet stream goes through the guy''s hand and rests on his head.  Wondering about meaning of title without comma after "Why".  Good rule of thirds.', '2007-06-11 17:04:55.000000', NULL, 1),
(3768923, 528761, 76430, '<td valign="top">The wall rather than the object of the title is in focus.  It does add to mystery about the guy though.</td>', 'The wall rather than the object of the title is in focus.  It does add to mystery about the guy though.', '2007-06-11 17:06:04.000000', NULL, 1),
(3768929, 527852, 76430, '<td valign="top">Good sharpness, coloring, composition and title.</td>', 'Good sharpness, coloring, composition and title.', '2007-06-11 17:07:30.000000', NULL, 1),
(3768937, 529211, 76430, '<td valign="top">If looks could kill!  The shell is a bit tilted, but you may have meant to do that to show it''s being held.</td>', 'If looks could kill!  The shell is a bit tilted, but you may have meant to do that to show it''s being held.', '2007-06-11 17:08:31.000000', NULL, 1),
(3768940, 527235, 76430, '<td valign="top">I''m not sure how this meets the challenge, but I like the effect.</td>', 'I''m not sure how this meets the challenge, but I like the effect.', '2007-06-11 17:09:48.000000', NULL, 1),
(3768963, 528759, 42181, '<td valign="top">Well i believe that it is due to the Archimedes''s principle, or was this a rhetorical question ;-)  Sorry couldn''t help myself.<br/>Nice picture, i like the detail of the rivets in the body work.</td>', 'Well i believe that it is due to the Archimedes''s principle, or was this a rhetorical question ;-)  Sorry couldn''t help myself.Nice picture, i like the detail of the rivets in the body work.', '2007-06-11 17:14:25.000000', NULL, 1),
(3768978, 526780, 42181, '<td valign="top">I can''t believe you painted this guys truck just so you could get a shot ;-) but you do have to ask the question, why?</td>', 'I can''t believe you painted this guys truck just so you could get a shot ;-) but you do have to ask the question, why?', '2007-06-11 17:18:00.000000', NULL, 1),
(3769024, 526795, 42181, '<td valign="top">Sweet, you can almost feel her (?) pain.</td>', 'Sweet, you can almost feel her (?) pain.', '2007-06-11 17:35:58.000000', NULL, 1),
(3769054, 528285, 43565, '<td valign="top">Maybe a better question would be "why stay?"</td>', 'Maybe a better question would be "why stay?"', '2007-06-11 17:45:31.000000', NULL, 1),
(3769126, 528816, 1024, '<td valign="top">This image definitely has humor. I think perhaps a small bump in the contrast would help the colors pop a bit more.  9</td>', 'This image definitely has humor. I think perhaps a small bump in the contrast would help the colors pop a bit more.  9', '2007-06-11 18:05:03.000000', NULL, 1),
(3769132, 528706, 1024, '<td valign="top">I love this photo, but at the same time it tears my heart out.  The sign of a truly fine photograph is that it causes emotion in the viewer.</td>', 'I love this photo, but at the same time it tears my heart out.  The sign of a truly fine photograph is that it causes emotion in the viewer.', '2007-06-11 18:06:17.000000', NULL, 1),
